  root.nextStatus=status=>{const index=root.statuses.indexOf(status);return index>=0&&index<root.statuses.length-1?root.statuses[index+1]:null};
  root.canTransition=function(from,to){if(from===to)return true;return root.nextStatus(from)===to};
  root.setStatus=function(id,status,eventText,options={}){const order=root.getOrder(id);if(!order||!root.statuses.includes(status))return false;const current=order.status;if(current&&root.statuses.includes(current)&&!root.canTransition(current,status)&&options.force!==true){console.warn(`CopySet blocked workflow jump: ${current} -> ${status}`);return false}order.status=status;if(status==='Tuotannossa'&&!order.productionStep)order.productionStep=root.config?.productionSteps?.[0]||'Aloitettu';if(status==='Valmis')order.productionStep=root.config?.productionSteps?.[2]||'Valmis';if(status==='Laskutusvalmis'){order.invoiceStatus='Tarkastettavana';order.invoiceCreatedAt=order.invoiceCreatedAt||new Date().toISOString()}if(status==='Laskutettu'){order.invoiceStatus='Hyväksytty';order.invoiceApprovedAt=order.invoiceApprovedAt||new Date().toISOString();order.invoicedAt=order.invoicedAt||new Date().toISOString()}const log=legacy.log();if(eventText&&log)try{log(order,eventText)}catch(error){console.error('CopySet event log failed',error)}root.persist(options);return order};
  root.legacy=Object.freeze({state:legacy.state});
