  function calc(){const q=Math.max(1,num(body.querySelector('#pq').value)),w=num(body.querySelector('#pw').value),margin=num(body.querySelector('#pm').value)||1,priceGroups=groups(),size=priceGroups.size[state.size],material=priceGroups.material[state.material],print=priceGroups.print[state.print],base=num(preset[2]),production=q*num(preset[1])*size[1]*material[1]*print[1]*(1+w/100)+size[2]+material[2]+print[2],rush=body.querySelector('#prush').checked?production*(num(defaults().calculation?.rush,25)/100):0,selectedExtras=[...body.querySelectorAll('[data-extra]')].filter(r=>r.querySelector('input[type=checkbox]').checked).map(r=>({name:r.querySelector('span')?.textContent?.trim()||'Lisätyö',price:num(r.querySelector('input[type=number]').value)})),extra=selectedExtras.reduce((s,x)=>s+x.price,0),cost=base+production+rush+extra,suggested=cost*margin,own=num(body.querySelector('#pown').value),total=own>0?own:suggested,profit=total-cost;body.querySelector('#pt').textContent=money(total);body.querySelector('#punit').textContent=money(total/q)+' / kpl · '+q+' kpl';body.querySelector('#plines').innerHTML=`<div class="pricing-line"><span>Aloitus</span><b>${money(base)}</b></div><div class="pricing-line"><span>Painatus</span><b>${money(production)}</b></div><div class="pricing-line"><span>Lisätyöt</span><b>${money(extra)}</b></div>${rush?`<div class="pricing-line"><span>Kiirelisä</span><b>${money(rush)}</b></div>`:''}<div class="pricing-line"><span>Kustannus yht.</span><b>${money(cost)}</b></div><div class="pricing-line"><span>Kate</span><b>${money(profit)}</b></div><div class="pricing-line pricing-total"><span>Myyntihinta</span><b>${money(total)}</b></div>`;return{qty:q,total,cost,note:body.querySelector('#pn').value,extras:selectedExtras,extrasTotal:extra,details:{size:size[0],material:material[0],print:print[0],waste:w,margin,rush:!!rush,extras:selectedExtras}}}
  body.addEventListener('input',calc);body.addEventListener('change',calc);body.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{state[b.dataset.choice]=num(b.dataset.i);body.querySelectorAll(`[data-choice="${b.dataset.choice}"]`).forEach(x=>x.classList.toggle('on',x===b));calc()});body.querySelectorAll('[data-qty]').forEach(b=>b.onclick=()=>{body.querySelector('#pq').value=b.dataset.qty;body.querySelectorAll('[data-qty]').forEach(x=>x.classList.toggle('on',x===b));calc()});body.querySelectorAll('.pricing-remove').forEach(b=>b.onclick=()=>{b.closest('[data-extra]').remove();calc()});body.querySelector('#padd').onclick=()=>{const n=body.querySelector('#pnewname'),p=body.querySelector('#pnewprice');if(!n.value.trim())return;body.querySelector('#pextras').insertAdjacentHTML('beforeend',`<div class="pricing-check" data-extra><input type="checkbox" checked><span>${esc(n.value.trim())}</span><input type="number" step=".01" value="${num(p.value)}"><button type="button" class="pricing-remove">×</button></div>`);const row=body.querySelector('#pextras [data-extra]:last-child');row.querySelector('.pricing-remove').onclick=()=>{row.remove();calc()};n.value='';p.value='';calc()};body.querySelector('#pricingUse').onclick=()=>{const result=calc();onUse?.(result);m.classList.remove('on')};m.classList.add('on');calc();return true
