 const products=o=>Array.isArray(o.products)&&o.products.length?o.products:[{name:o.product,qty:o.qty,desc:o.description,extras:o.extraLines||[]}];
 function field(p,names){for(const n of names){if(p&&p[n]!=null&&p[n]!=='')return p[n]}return ''}
 function remove(id){const o=orderById(id),s=root.state?.();if(!o||!s||!Array.isArray(s.orders))return false;if(!confirm('Poistetaanko '+(o.mode==='Tarjous'?'tarjous ':'tilaus ')+(o.no||'')+'?'))return false;s.orders=s.orders.filter(x=>String(x.id)!==String(id));root.persist?.();if(typeof closeM==='function')closeM();return true}
 function setProductionStep(id,step){const allowed=root.config?.productionSteps||['Aloitettu','Käynnissä','Valmis'],o=orderById(id);if(!o||o.status!=='Tuotannossa'||!allowed.includes(step))return false;const current=allowed.indexOf(o.productionStep||allowed[0]),next=allowed.indexOf(step);if(next<current||next>current+1)return false;o.productionStep=step;root.persist?.();root.orderPage?.open?.(id);return true}
